CREATE TABLE IF NOT EXISTS rudel.call_facts
(
  `organization_id` String COMMENT 'Owning workspace ID; tenant boundary.',
  `user_id` String COMMENT 'Session owner.',
  `session_id` String COMMENT 'Native session ID within organization and user.',
  `revision` UInt64 COMMENT 'Raw transcript revision of the run index build\'s generation.',
  `parser_version` UInt16 COMMENT 'Transcript records parser version of the generation.',
  `index_version` UInt16 COMMENT 'Run index rules version of the build.',
  `build_revision` UInt64 COMMENT 'Run index build that wrote the row; the session\'s newest run index receipt names the build readers read.',
  `agent_id` String COMMENT 'Transcript stream; empty for the main stream.',
  `record_idx` UInt32 COMMENT 'Raw record index of the call\'s first tool_call record.',
  `block_idx` UInt16 COMMENT 'Block of that record.',
  `source` LowCardinality(String) COMMENT 'Transcript source: claude_code or codex.',
  `stream_kind` LowCardinality(String) COMMENT 'main, subagent (a Claude Code subagent stream) or codex_thread (a Codex thread a parent started: a stream of the session, or a session whose thread_source is subagent).',
  `call_id` String COMMENT 'The call\'s id within its stream, as recorded.',
  `run_id` String COMMENT 'Run node id of the call\'s run (run_index.run_id); empty for a call before its stream\'s first prompt.',
  `turn_idx` UInt32 COMMENT 'Run number within the stream; 0 before the first prompt.',
  `repository` String COMMENT 'The session\'s repository key as uploaded (run_index.repository).',
  `model` LowCardinality(Nullable(String)) COMMENT 'Model of the response that made the call (run_requests.usage_model), else of its run (run_index.model); NULL when neither names one.',
  `run_started_at` Nullable(DateTime64(3, 'UTC')) COMMENT 'When the call\'s run started; NULL without a run.',
  `session_date` DateTime64(3, 'UTC') COMMENT 'Session date of the generation.',
  `built_at` DateTime64(3, 'UTC') COMMENT 'UTC millisecond time the worker wrote the row.',
  `call_level` LowCardinality(String) COMMENT 'top, script (a Codex code-mode script) or inner (a call a script ran).',
  `parent_call_id` String COMMENT 'For an inner call, the call_id of the script that ran it.',
  `tool_name` LowCardinality(String) COMMENT 'Tool the agent called, as recorded.',
  `started_at` DateTime64(3, 'UTC') COMMENT 'Timestamp of the call record.',
  `finished_at` Nullable(DateTime64(3, 'UTC')) COMMENT 'When the call\'s work finished: its background task\'s ending notification, else its last result; NULL when unknown.',
  `call_minutes` Nullable(Float64) COMMENT 'Minutes from the call record to finished_at; NULL when unknown.',
  `has_result` UInt8 COMMENT '1 when the call has a result in the transcript.',
  `failed` UInt8 COMMENT '1 when a result is an error or exits non-zero, or its background task ended failed or killed.',
  `error_from_call_id` String COMMENT 'On a script whose failure an inner call records, that inner call\'s call_id.',
  `exit_code` Nullable(Int32) COMMENT 'Exit code a result or its background task recorded.',
  `denial_kind` LowCardinality(String) COMMENT 'Why the call was refused before it ran; empty when it was not.',
  `denial_reason` String COMMENT 'What the refusal said; empty when none was recorded.',
  `interrupted` Nullable(UInt8) COMMENT '1 when a result records an interruption; NULL when the stream cannot record it.',
  `timed_out` Nullable(UInt8) COMMENT '1 when the call\'s own timeout stopped it; NULL when the stream cannot record it.',
  `timed_out_after_ms` Nullable(UInt32) COMMENT 'The timeout limit in milliseconds; NULL when timed_out is not 1.',
  `backgrounded` UInt8 COMMENT '1 when the call\'s work went on in the background.',
  `task_id` Nullable(String) COMMENT 'The background task\'s id; NULL when not backgrounded.',
  `background_status` Nullable(String) COMMENT 'completed, failed, killed or stopped, from the latest task notification; NULL when none reported an end.',
  `background_exit_code` Nullable(Int32) COMMENT 'Exit code the background task\'s latest notification reported.',
  `file_path` String COMMENT 'File the call names, else the first file it changes; absolute where the working directory is known (parser 15).',
  `file_op` LowCardinality(String) COMMENT 'read, write, edit or delete for file_path; empty otherwise.',
  `command_class` LowCardinality(String) COMMENT 'The shell command\'s class, the first by precedence.',
  `command_classes` Array(String) COMMENT 'The class of each program the shell command runs.',
  `command_from` String COMMENT 'command or script; empty when the call carries no command (the calls view\'s meaning).',
  `command` Nullable(String) COMMENT 'The command or script text as stored (its stored start when only that is); NULL when the call carries none.',
  `command_chars` Nullable(UInt64) COMMENT 'Characters of the command; NULL when only part is stored or there is none.',
  `command_argv0` Nullable(String) COMMENT 'The program the shell command runs, computed at build time.',
  `command_prefix` Nullable(String) COMMENT 'The program and its subcommand, computed at build time.',
  `command_programs` Array(String) COMMENT 'Each program of the command\'s chains and pipelines.',
  `command_prefixes` Array(String) COMMENT 'Each program with its subcommand, as command_programs lists them.',
  `command_fingerprint` Nullable(UInt64) COMMENT 'cityHash64 of the normalized command.',
  `command_simhash` Nullable(UInt64) COMMENT 'Word-shingle simhash of the normalized command; NULL under 20 words.',
  `command_head` Nullable(String) COMMENT 'The first 300 bytes of a shell command\'s stored text.',
  `changed_files` Array(String) COMMENT 'Every file the call asks to change, in order.',
  `changed_file_ops` Array(String) COMMENT 'write, edit or delete for each of changed_files.',
  `changed_files_basis` Array(String) COMMENT 'tool, shell or script for each of changed_files.',
  `files_read` Array(String) COMMENT 'Every file the call reads, in order.',
  `setup_files_read` Array(String) COMMENT 'The setup files (received setup naming) of the instruction and skill files among files_read: CLAUDE.md, CLAUDE.local.md, AGENTS.md, AGENTS.override.md, SKILL.md and .claude/rules files.',
  `setup_paths_read` Array(String) COMMENT 'The path read for each of setup_files_read.',
  `edit_route` LowCardinality(String) COMMENT 'How the call changed files; empty when it changed none.',
  `error` Nullable(String) COMMENT 'The line of a failed or refused call\'s result that names the error, up to 300 bytes; NULL otherwise.',
  `output_chars` UInt64 COMMENT 'Characters of the call\'s results before any cap.',
  `output_cut` UInt8 COMMENT '1 when part of the output was not stored; the output text stays in transcript_records.',
  INDEX started_at_minmax started_at TYPE minmax GRANULARITY 1
) ENGINE = ReplacingMergeTree(build_revision)
PRIMARY KEY (`organization_id`, `user_id`, `session_id`, `revision`, `parser_version`, `index_version`, `build_revision`, `agent_id`, `record_idx`, `block_idx`)
ORDER BY (`organization_id`, `user_id`, `session_id`, `revision`, `parser_version`, `index_version`, `build_revision`, `agent_id`, `record_idx`, `block_idx`)
SETTINGS index_granularity = 1024, index_granularity_bytes = 1048576, non_replicated_deduplication_window = 1000, storage_policy = 's3'
COMMENT 'L1 tool calls of each run index build, every stream, one row per call with its command identity, files and outcome; committed by the build\'s run index receipt; written only by the reconciliation worker.';
